fn combined_weight(keys: [str]) -> [int]:
    """For each key, in order, the sum of its two values."""
    n = len(keys)
    results = parallel([lambda: weight(keys[i // 2]) if i % 2 == 0 else delay(keys[i // 2]) for i in range(2 * n)])
    return [results[2 * j] + results[2 * j + 1] for j in range(n)]

